mapper.select:
SELECT 
FROM mr_archive_box_record abr
WHERE abr.bah = #{normalizedCode}
   OR abr.sjh = #{normalizedCode}
   OR (
        abr.bah ~ '^[0-9]+$'
        AND COALESCE(NULLIF(LTRIM(abr.bah, '0'), ''), '0') = #{searchCode}
   )
   OR (
        abr.sjh ~ '^[0-9]+$'
        AND COALESCE(NULLIF(LTRIM(abr.sjh, '0'), ''), '0') = #{searchCode}
   )
   OR EXISTS (
        SELECT 1
        FROM mr_statistics s
        WHERE 
          AND (
              s.bah = #{normalizedCode}
              OR s.sjh = #{normalizedCode}
              OR (
                  s.bah ~ '^[0-9]+$'
                  AND COALESCE(NULLIF(LTRIM(s.bah, '0'), ''), '0') = #{searchCode}
              )
              OR (
                  s.sjh ~ '^[0-9]+$'
                  AND COALESCE(NULLIF(LTRIM(s.sjh, '0'), ''), '0') = #{searchCode}
              )
          )
   )
ORDER BY abr.updated_at DESC, abr.id DESC

SELECT box_no AS boxNo, COUNT(*) AS recordCount, SUM(CASE WHEN status != 'NORMAL' THEN 1 ELSE 0 END) AS abnormalCount, MAX(updated_at) AS updatedAt FROM mr_archive_box_record WHERE box_no IS NOT NULL AND TRIM(box_no) != ''
AND box_no ILIKE '%' || #{keyword} || '%'
GROUP BY box_no ORDER BY box_no LIMIT #{limit} OFFSET #{offset}
